package org.apache.commons.lang.math;

import java.io.*;
import java.math.*;
import java.math.BigInteger;
import java.util.*;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

public class Fraction_divideBy_TriageGen0Test {

    @Test
    public void testDivideBy_ValidFraction() {
        // Test 1/2 divided by 3/4 should be (1/2) * (4/3) = 4/6 = 2/3
        Fraction f1 = Fraction.getFraction(1, 2);
        Fraction f2 = Fraction.getFraction(3, 4);
        Fraction expected = Fraction.getReducedFraction(2, 3);
        Fraction result = f1.divideBy(f2);
        assertEquals(expected, result);
    }

    @Test
    public void testDivideBy_DivideByOne() {
        Fraction f1 = Fraction.getFraction(5, 7);
        Fraction f2 = Fraction.getFraction(1, 1);
        Fraction result = f1.divideBy(f2);
        assertEquals(f1, result);
    }

    @Test
    public void testDivideBy_ResultIsInteger() {
        Fraction f1 = Fraction.getFraction(1, 2);
        Fraction f2 = Fraction.getFraction(1, 4);
        Fraction expected = Fraction.getFraction(2, 1);
        Fraction result = f1.divideBy(f2);
        assertEquals(expected, result);
    }

    @Test(expected = IllegalArgumentException.class)
    public void testDivideBy_NullParameter() {
        Fraction f1 = Fraction.getFraction(1, 2);
        f1.divideBy(null);
    }

    @Test(expected = ArithmeticException.class)
    public void testDivideBy_DivideByZeroNumerator() {
        Fraction f1 = Fraction.getFraction(1, 2);
        Fraction f2 = Fraction.getFraction(0, 5);
        f1.divideBy(f2);
    }

    @Test
    public void testDivideBy_NegativeNumerator() {
        // 1/2 divided by -3/4 should be (1/2) * (-4/3) = -4/6 = -2/3
        Fraction f1 = Fraction.getFraction(1, 2);
        Fraction f2 = Fraction.getFraction(-3, 4);
        Fraction expected = Fraction.getReducedFraction(-2, 3);
        Fraction result = f1.divideBy(f2);
        assertEquals(expected, result);
    }

    @Test
    public void testDivideBy_NegativeDenominator() {
        // 1/2 divided by 3/-4 should be (1/2) * (-4/3) = -2/3
        Fraction f1 = Fraction.getFraction(1, 2);
        Fraction f2 = Fraction.getFraction(3, -4);
        Fraction expected = Fraction.getReducedFraction(-2, 3);
        Fraction result = f1.divideBy(f2);
        assertEquals(expected, result);
    }
}
